/*===========================
  teams css 
===========================*/
.team-style-one {
  position: relative;
  margin-top: 30px;
  box-shadow: var(--shadow-2);
  border-radius: 8px;
  overflow: hidden;
  -webkit-transition: all 0.4s ease-out 0s;
  -moz-transition: all 0.4s ease-out 0s;
  -ms-transition: all 0.4s ease-out 0s;
  -o-transition: all 0.4s ease-out 0s;
  transition: all 0.4s ease-out 0s;
}
.team-style-one:hover {
  box-shadow: var(--shadow-4);
}
.team-style-one .team-image img {
  width: 100%;
}
.team-style-one .team-content {
  padding: 20px 15px;
  width: 100%;
  background-color: var(--white);
}
.team-style-one .team-content .name {
  font-size: 20px;
  font-weight: 600;
  line-height: 30px;
  color: var(--black);
  -webkit-transition: all 0.3s ease-out 0s;
  -moz-transition: all 0.3s ease-out 0s;
  -ms-transition: all 0.3s ease-out 0s;
  -o-transition: all 0.3s ease-out 0s;
  transition: all 0.3s ease-out 0s;
}
@media only screen and (min-width: 992px) and (max-width: 1199px) {
  .team-style-one .team-content .name {
    font-size: 20px;
  }
}
.team-style-one .team-content .sub-title {
  font-size: 15px;
  line-height: 24px;
  color: var(--dark-3);
  margin-top: 2px;
  display: block;
}
.team-style-one .team-content .social {
  margin-top: 12px;
}
.team-style-one .team-content .social li {
  display: inline-block;
  margin: 0 4px;
}
.team-style-one .team-content .social li a {
  font-size: 16px;
  color: var(--gray-1);
  height: 35px;
  width: 35px;
  text-align: center;
  line-height: 35px;
  border: 1px solid var(--gray-4);
  border-radius: 50%;
  -webkit-transition: all 0.4s ease-out 0s;
  -moz-transition: all 0.4s ease-out 0s;
  -ms-transition: all 0.4s ease-out 0s;
  -o-transition: all 0.4s ease-out 0s;
  transition: all 0.4s ease-out 0s;
}
.team-style-one .team-content .social li a:hover {
  background-color: var(--primary);
  color: var(--white);
  border-color: transparent;
}

/*===== TEAM STYLE 2 =====*/
.primary-btn { background: var(--secondary); color: var(--white); box-shadow: var(--shadow-2); padding: 12px 26px; border-radius: 6px; font-weight: 600; border: none; }
.primary-btn:hover { background: var(--secondary-dark); color: var(--white); box-shadow: var(--shadow-4); }
.outline-btn { border: 1.5px solid var(--secondary); color: var(--secondary); padding: 11px 24px; border-radius: 6px; font-weight: 600; background: transparent; }
.outline-btn:hover { background: var(--secondary); color: var(--white); }
.teams-style-3 { background: var(--light-2); padding: 70px 0; }
.teams-style-3 .section-box { background: var(--white); border: 1px solid var(--gray-4); border-radius: 16px; padding: 42px 34px; box-shadow: var(--shadow-2); }
.teams-style-3 .tag-label { color: var(--secondary); font-size: 13px; font-weight: 700; letter-spacing: .06em; }
.teams-style-3 h2, .teams-style-3 h5 { color: var(--black); }
.teams-style-3 p { color: var(--dark-2); }
.teams-style-3 .mini-card { padding: 24px; border-radius: 12px; background: var(--light-2); border: 1px solid var(--gray-4); height: 100%; }
.teams-style-3 .mini-card i { color: var(--secondary); }

